verification_receipts.patch_excerpt:
diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..7789c4d 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -185,4 +185,44 @@ for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command',
 }
 assert.equal(replay.model_status, 'unknown');

+// Adversarial regression: a trusted observation naming a different registered model
+// than the one requested (e.g. reporting the codex-hosted model for the local-qwen
+// branch) must fail, never pass -- and missing telemetry on that same observation
+// must stay unknown rather than being inferred as known/passing.
+const substitutedObservation = Object.freeze({ model: codex.model, trusted: true });
+assert.notEqual(substitutedObservation.model, local.model);
+const substitutionProof = profiles.evaluateModelProof(local, substitutedObservation);
+assert.equal(substitutionProof.status, 'failed');
+assert.equal(substitutionProof.reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.equal(substitutionProof.requested_model, local.model);
+assert.equal(substitutionProof.observed_model, codex.model);
+
+const substitutionState = profiles.missionControlExecutorState({
+  profile: local, observation: substitutedObservation, wrapper: null,
+});
+assert.equal(substitutionState.requested_model, local.model);
+assert.equal(substitutionState.observed_model, codex.model);
+assert.equal(substitutionState.model_status, 'failed');
+assert.notEqual(substitutionState.model_status, 'passed');
+assert.equal(substitutionState.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.equal(substitutionState.duration_ms, null);
+assert.equal(substitutionState.duration_status, 'unknown');
+assert.equal(substitutionState.tokens, null);
+assert.equal(substitutionState.tokens_status, 'unknown');
+assert.equal(substitutionState.cost, null);
+assert.equal(substitutionState.cost_status, 'unknown');
+assert.equal(substitutionState.receipt_status, 'unknown');
+
+const substitutionReplay = profiles.publicExecutorReplay({
+  profile: local, observation: substitutedObservation, wrapper: null,
+});
+assert.equal(substitutionReplay.model_status, 'failed');
+assert.equal(substitutionReplay.duration_status, 'unknown');
+assert.equal(substitutionReplay.tokens_status, 'unknown');
+assert.equal(substitutionReplay.cost_status, 'unknown');
+const substitutionSerialized = JSON.stringify(substitutionReplay);
+for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command', 'args']) {
+  assert(!substitutionSerialized.includes(forbidden), `public executor replay leaked ${forbidden}`);
+}
+
 process.stdout.write('Executor profiles passed: strict profiles, canonical digests, literal invocations, bound receipts, and honest model proof.\n');
